  private disposeWorld(group:THREE.Group){group.traverse(object=>{if(object instanceof THREE.Sprite){object.material.map?.dispose();object.material.dispose();return;}if(!(object instanceof THREE.Mesh||object instanceof THREE.Points||object instanceof THREE.Line))return;object.geometry.dispose();const materials=Array.isArray(object.material)?object.material:[object.material];materials.forEach(material=>material.dispose());});group.clear();}
