  private buildEnvironmentWorld(){this.applyTrackTheme();if(this.trackLayout.theme.environment==="aurora-ridge")this.addAuroraRidge();else if(this.trackLayout.theme.environment==="solar-foundry")this.addSolarFoundry();else this.addCity();if(this.trackLayout.theme.environment!=="solar-foundry")this.addStars();}
  private rebuildTrack(trackId:string){const next=TRACKS.find(track=>track.id===trackId&&track.available)??TRACKS[0];if(next.id===this.currentTrack.id)return;this.currentTrack=next;this.trackLayout=getTrackLayout(next.id);this.curve=makeTrack(this.trackLayout);this.trackLength=this.curve.getLength();this.boostPads=[...this.trackLayout.boostPads];this.disposeWorld(this.trackWorld);this.disposeWorld(this.environmentWorld);this.buildTrackWorld();this.buildEnvironmentWorld();this.updateTransforms(0);}
  private addRails(){
    const material=new THREE.MeshBasicMaterial({color:this.trackLayout.theme.rail,toneMapped:false});
    for(const side of [-1,1]){
      let points:THREE.Vector3[]=[];
      const flush=()=>{if(points.length>2)this.trackWorld.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points,false,"centripetal"),Math.max(12,points.length*2),.055,5,false),material));points=[];};
      for(let i=0;i<=SAMPLES;i++){const progress=i/SAMPLES;if(isGap(progress,this.trackLayout)){flush();continue;}const f=frame(this.curve,progress,this.trackLayout);points.push(f.center.clone().addScaledVector(f.right,side*(TRACK_WIDTH/2+.12)).addScaledVector(f.up,.34));}
      flush();
    }
    for(let i=0;i<112;i++){const progress=i/112;if(isGap(progress,this.trackLayout))continue;const f=frame(this.curve,progress,this.trackLayout),color=i%8===0?this.trackLayout.theme.accent:this.trackLayout.theme.rail;for(const side of [-1,1]){const post=new THREE.Mesh(new THREE.BoxGeometry(.09,.85,.09),new THREE.MeshBasicMaterial({color,toneMapped:false}));post.position.copy(f.center).addScaledVector(f.right,side*(TRACK_WIDTH/2+.12)).addScaledVector(f.up,.38);post.quaternion.copy(f.quaternion);this.trackWorld.add(post);}}
  }
