  private addEnergyStrips(){const material=new THREE.MeshBasicMaterial({color:0x4dffb8,transparent:true,opacity:.9,toneMapped:false});for(const [start,end] of this.trackLayout.energy){for(let progress=start;progress<=end;progress+=.004){const f=frame(this.curve,progress,this.trackLayout);for(const side of [-1,1]){const strip=new THREE.Mesh(new THREE.BoxGeometry(4.4,.045,5.5),material);strip.position.copy(f.center).addScaledVector(f.right,side*(TRACK_WIDTH/2-3)).addScaledVector(f.up,.035);strip.quaternion.copy(f.quaternion);this.trackWorld.add(strip);}}}}
