  private bindEvents(){this.addEvent(window,"resize",()=>this.resize());this.addEvent(window,"keydown",event=>{this.keys.add(event.code);if(event.code==="Escape")this.togglePause();if(event.code==="KeyM"&&!event.repeat)this.toggleMinimap();});this.addEvent(window,"keyup",event=>this.keys.delete(event.code));this.renderer.xr.addEventListener("sessionstart",()=>{this.snapshot.vrActive=true;this.snapshot.inputMode="vr";const racing=this.snapshot.phase==="racing"||this.snapshot.phase==="countdown";this.cockpit.visible=racing;this.ship.visible=racing;this.mapPanel.visible=racing&&this.snapshot.minimapVisible;this.speedPanel.visible=racing;this.vrMenuPanel.visible=this.vrMenuActive;this.vrShipPreview.visible=this.vrMenuActive&&this.vrMenuStep==="ship";this.vrTrackPreview.visible=this.vrMenuActive&&this.vrMenuStep==="track";this.renderer.setPixelRatio(1);this.renderer.xr.setFoveation(.65);this.emitSnapshot(true);});this.renderer.xr.addEventListener("sessionend",()=>{this.snapshot.vrActive=false;this.vrMenuActive=false;this.vrMenuPanel.visible=false;this.vrShipPreview.visible=false;this.vrTrackPreview.visible=false;this.cockpit.visible=true;this.ship.visible=true;this.hideVrPointers();this.mapPanel.visible=false;this.speedPanel.visible=false;this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));this.resize();this.emitSnapshot(true);});}
