  setAudioSettings(settings:AudioSettings){this.audioSettings={master:clamp(settings.master,0,1),music:clamp(settings.music,0,1),sfx:clamp(settings.sfx,0,1),muted:Boolean(settings.muted)};this.audio.setSettings(this.audioSettings);this.syncAudioSettings?.({...this.audioSettings});}
